def __init__(self, charge, adducts=None):
    if adducts is None:
        # Positive charge states are carried by protons, negative ones by
        # electrons, as defined by the ProForma specification. For protons
        # the signed count mirrors the (signed) charge so that the carrier
        # mass is added with the correct sign; the electron count stays
        # positive because it is a count of added electrons.
        if charge < 0:
            adducts = [Adduct("e-", -1, -charge)]
        else:
            adducts = [Adduct("H", 1, charge)]
    self.charge = charge
    self.adducts = adducts

