@staticmethod
def _formula_tag_charge(tag) -> int:
    '''Return the local charge carried by a single elemental formula
    modification tag, or ``0`` if the tag carries no local charge.
    '''
    if not isinstance(tag, FormulaModification):
        return 0
    charge = tag.definition.get('charge')
    return int(charge) if charge else 0

'''
The sum of the local charges (``:z...`` valence) contributed by every
elemental formula modification on this peptidoform, whether localised
on a residue, applied as a fixed (global) modification, or present as a
labile / unlocalized / interval modification.

Returns
-------
int
    The aggregate local charge of the peptidoform.
'''
total = 0
for tag in self.tags:
    total += self._formula_tag_charge(tag)
for rule in self.properties['fixed_modifications']:
    tag = rule.modification_tag
    for i, (aa, _position_tags) in enumerate(self.sequence):
        if rule.is_valid(aa.upper(), i == 0, i == len(self.sequence) - 1):
            total += self._formula_tag_charge(tag)
for collection_name in (
    'labile_modifications',
    'unlocalized_modifications',
    'n_term',
    'c_term',
):
    for tag in self.properties.get(collection_name) or []:
        total += self._formula_tag_charge(tag)
for interval in self.properties['intervals']:
    for tag in interval.tags:
        total += self._formula_tag_charge(tag)
return total

